const { withAndroidManifest, withDangerousMod } = require('expo/config-plugins');
const fs = require('node:fs/promises');
const path = require('node:path');

const RESOURCE_NAME = 'qldu_private_data_extraction_rules';
const BACKUP_DOMAINS = Object.freeze([
  'root', 'file', 'database', 'sharedpref', 'external',
  'device_root', 'device_file', 'device_database', 'device_sharedpref',
]);
const exclusions = BACKUP_DOMAINS.map(domain => `    <exclude domain="${domain}" path="." />`).join('\n');
const DATA_EXTRACTION_XML = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by withPrivateStorage. No app data is eligible for cloud backup or device transfer. -->
<data-extraction-rules>
  <cloud-backup disableIfNoEncryptionCapabilities="true">
${exclusions}
  </cloud-backup>
  <device-transfer>
${exclusions}
  </device-transfer>
</data-extraction-rules>
`;
function applyPrivateStorageManifest(manifest) {
  const applications = manifest?.manifest?.application;
  if (!Array.isArray(applications) || !applications.length) throw new Error('Android application manifest is required for private storage rules.');
  for (const application of applications) {
    application.$ = application.$ || {};
    application.$['android:allowBackup'] = 'false';
    application.$['android:fullBackupContent'] = 'false';
    application.$['android:dataExtractionRules'] = `@xml/${RESOURCE_NAME}`;
  }
  return manifest;
}
async function writeDataExtractionRules(platformProjectRoot, fileSystem = fs) {
  if (typeof platformProjectRoot !== 'string' || !path.isAbsolute(platformProjectRoot)) throw new Error('Android project root is required.');
  const directory = path.join(platformProjectRoot, 'app', 'src', 'main', 'res', 'xml');
  await fileSystem.mkdir(directory, { recursive: true });
  await fileSystem.writeFile(path.join(directory, `${RESOURCE_NAME}.xml`), DATA_EXTRACTION_XML, 'utf8');
}
function withPrivateStorage(config) {
  config = withAndroidManifest(config, result => {
    result.modResults = applyPrivateStorageManifest(result.modResults);
    return result;
  });
  return withDangerousMod(config, ['android', async result => {
    await writeDataExtractionRules(result.modRequest.platformProjectRoot);
    return result;
  }]);
}
module.exports = withPrivateStorage;
module.exports.applyPrivateStorageManifest = applyPrivateStorageManifest;
module.exports.writeDataExtractionRules = writeDataExtractionRules;
module.exports.DATA_EXTRACTION_XML = DATA_EXTRACTION_XML;
module.exports.BACKUP_DOMAINS = BACKUP_DOMAINS;
module.exports.RESOURCE_NAME = RESOURCE_NAME;
